--
-- Table structure for table `gastos_comunes`
--

DROP TABLE IF EXISTS `gastos_comunes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `gastos_comunes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `categoria_id` int(11) DEFAULT NULL,
  `mes` int(11) DEFAULT NULL,
  `anio` int(11) DEFAULT NULL,
  `descripcion` text NOT NULL,
  `tipo_gasto` enum('comun','individual') NOT NULL DEFAULT 'comun',
  `edificio_id` int(11) DEFAULT NULL,
  `monto_total` decimal(10,2) DEFAULT 0.00,
  `fecha` date NOT NULL,
  `fecha_gasto` date DEFAULT NULL,
  `proveedor` varchar(150) DEFAULT NULL,
  `nro_factura_proveedor` varchar(50) DEFAULT NULL,
  `soporte_digital` varchar(255) DEFAULT NULL,
  `soporte_hash` char(64) DEFAULT NULL,
  `pagina_soporte` int(11) DEFAULT 1,
  `extracto_texto` text DEFAULT NULL,
  `periodo` varchar(20) DEFAULT NULL,
  `admin_id` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `dup_guard` varchar(191) GENERATED ALWAYS AS (if(`deleted_at` is not null,NULL,if(`nro_factura_proveedor` is null or `nro_factura_proveedor` = '',concat('S|',ifnull(`mes`,0),'|',ifnull(`anio`,0),'|',ifnull(`categoria_id`,0),'|',ifnull(`monto_total`,0),'|',ifnull(`fecha_gasto`,'0000-00-00'),'|',left(ifnull(`proveedor`,''),45),'|',left(`descripcion`,60),'|',`tipo_gasto`,'|',ifnull(`edificio_id`,0)),concat('F|',ifnull(`mes`,0),'|',ifnull(`anio`,0),'|',left(`nro_factura_proveedor`,50),'|',left(ifnull(`proveedor`,''),45))))) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gasto_dup_guard` (`dup_guard`),
  KEY `idx_gastos_periodo` (`periodo`),
  KEY `idx_gastos_categoria` (`categoria_id`),
  KEY `fk_gastos_edificio` (`edificio_id`),
  KEY `idx_gastos_soporte_hash` (`soporte_hash`),
  CONSTRAINT `fk_gastos_edificio` FOREIGN KEY (`edificio_id`) REFERENCES `edificios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2609 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

